const { useReducer } = React;

function quantityReducer(state, action) {
  if (action.type === 'increase') return state + 1;
  if (action.type === 'decrease') return Math.max(0, state - 1);
  if (action.type === 'reset') return 0;
  return state;
}

function Quantity() {
  const [quantity, dispatch] = useReducer(quantityReducer, 0);

  return (
    <section>
      <p>수량: {quantity}</p>
      <button type="button" onClick={() => dispatch({ type: 'increase' })}>증가</button>
      <button type="button" onClick={() => dispatch({ type: 'decrease' })}>감소</button>
      <button type="button" onClick={() => dispatch({ type: 'reset' })}>초기화</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Quantity />);

